/**
 * Timed online-assessment practice tests. Formats are modelled on PUBLIC listing text only
 * (question counts / time limits / topic lists shown on the reference's free catalogue page, Oct 2026).
 * All questions are generated by original families in engines/families.ts. No reference questions are used.
 * `observed` lists exactly which format facts came from the public listing; everything else is designed here.
 */
import type { GameMeta, SettingDef } from './types';
import { FAMILIES } from './engines/families';

export interface TestSpec {
  id: string;
  name: string;
  modelledOn: string;
  summary: string;
  questions: number;
  minutes: number;
  format: 'typed' | 'choice';
  mix: Record<string, number>;
  negativeMarking?: boolean;
  observed: string[];
  designed: string[];
}

