const n = (key: string, label: string, min: number, max: number, step = 1, unit?: string, help?: string): SettingDef => ({ key, label, type: 'number', min, max, step, unit, help });
export const TEST_ID_PREFIX = 'oa-';

export function testMeta(s: TestSpec): GameMeta {
  const real = { level: 'hard', questions: s.questions, duration: s.minutes * 60, format: s.format, negativeMarking: !!s.negativeMarking, allowSkip: true, adaptive: false };
  return {
    id: s.id, name: s.name, category: 'assessment', summary: `${s.summary} Format modelled on the ${s.modelledOn}.`,
    howTo: [
      `Real format: ${s.questions} questions in ${s.minutes} minutes${s.format === 'choice' ? ', multiple choice' : ', typed answers'}.`,
      'Hard uses that format. Medium gives 1.5× the time; Easy gives double time and easier questions. Custom changes anything.',
      'Skip moves on without penalty. The results break your score down by topic.',
      `Topics: ${Object.keys(s.mix).map((k) => FAMILIES[k].label).join(', ')}.`,
    ],
    controls: ['Enter submits', '1–4 choose an option', 'S skips', 'Esc leaves'],
    verification: s.observed.length > 1 ? 'rules-observed' : 'description-only',
    unverified: [`Observed on the public listing: ${s.observed.join('; ')}.`, `Designed here: ${s.designed.join('; ')}.`, 'All questions are original and generated; none come from the reference or the firm.', 'Not affiliated with or endorsed by the firm named.'],
    settings: [
      { key: 'level', label: 'Question level', type: 'select', options: [{ value: 'easy', label: 'Easy' }, { value: 'medium', label: 'Medium' }, { value: 'hard', label: 'Hard' }] },
      n('questions', 'Questions', 0, 200, 1, undefined, '0 = until time runs out'),
      n('duration', 'Time limit', 0, 14400, 30, 's', '0 = untimed'),
      { key: 'format', label: 'Answer format', type: 'select', options: [{ value: 'typed', label: 'Type the answer' }, { value: 'choice', label: 'Multiple choice' }] },
      { key: 'negativeMarking', label: 'Negative marking', type: 'boolean' },
      { key: 'allowSkip', label: 'Allow skipping', type: 'boolean' },
      { key: 'adaptive', label: 'Adapt difficulty as you go', type: 'boolean' },
    ],
    presets: {
      easy: { ...real, level: 'easy', duration: s.minutes * 120 },
      medium: { ...real, level: 'medium', duration: s.minutes * 90 },
      hard: real,
    },
    scoreLabel: 'Score', scoreFormat: 'count', higherIsBetter: true,
  };
}
export const TEST_BY_ID: Record<string, TestSpec> = Object.fromEntries(TEST_SPECS.map((s) => [s.id, s]));
